+
+static constexpr int TILE = 64;
+
+static void compute_tile(int n, const float* A, const float* B, float* C,
+                         int i0, int j0, int k0, int ti, int tj, int tk) {
+    int i_end = std::min(i0 + ti, n);
+    int j_end = std::min(j0 + tj, n);
+    int k_end = std::min(k0 + tk, n);
+
+    for (int i = i0; i < i_end; ++i) {
+        for (int k = k0; k < k_end; ++k) {
+            float a = A[i * n + k];
+            int j = j0;
+#if defined(__ARM_NEON)
+            // Vectorized loop: process 4 elements at a time
+            for (; j + 3 < j_end; j += 4) {
+                float32x4_t b_vec = vld1q_f32(B + k * n + j);
+                float32x4_t c_vec = vld1q_f32(C + i * n + j);
+                c_vec = vfmaq_n_f32(c_vec, b_vec, a);
+                vst1q_f32(C + i * n + j, c_vec);
+            }
+#endif
+            // Remainder loop
+            for (; j < j_end; ++j) {
+                C[i * n + j] += a * B[k * n + j];
+            }
+        }
+    }
+}
